"""Adapter around the assigned A-Maze-ing maze generator."""

from mazegenerator import MazeGenerator
import sys


class Maze:
    """Maze grid generated by the A-Maze-ing package.

    Each cell is a 4-bit wall mask: 1 = north, 2 = east, 4 = south,
    8 = west. A cell equal to 15 is fully closed.
    """
    def __init__(self, width: int, height: int, seed: int) -> None:
        """Generate the maze with the assigned package.

        Exits with a message if the generator fails.
        """
        try:
            mg = MazeGenerator(size=(width, height), perfect=False, seed=seed)
            self.grid: list[list[int]] = mg.maze
        except Exception as e:
            print(f"Maze generation failed: {e}")
            sys.exit(1)
        self.width = width
        self.height = height

    def can_move(self, x: int, y: int, dx: int, dy: int) -> bool:
        """Check if a move from (x, y) in direction (dx, dy) is possible.

        Returns:
            True if the target cell is inside the maze and no wall blocks it.
        """
        nx, ny = x + dx, y + dy
        if not (0 <= nx < self.width and 0 <= ny < self.height):
            return False
        if dx == 1:
            bit = 2
        elif dx == -1:
            bit = 8
        elif dy == -1:
            bit = 1
        else:
            bit = 4
        return (self.grid[y][x] & bit) == 0

    def get_center(self) -> tuple[int, int]:
        """Get the center cell of the maze.

        Returns:
            The (x, y) position of the center.
        """
        return (self.width // 2, self.height // 2)

    def get_corners(self) -> list[tuple[int, int]]:
        """Get the four corner cells of the maze.

        Returns:
            The (x, y) positions of the top-left, top-right, bottom-left
            and bottom-right corners.
        """
        return [(0, 0),
                (self.width - 1, 0),
                (0, self.height - 1),
                (self.width - 1, self.height - 1)]
